#create SSID with wifi
function configure_wifi_ssid()
{
	#connect to wifi
	echo "....................................................."
	echo "Removed existing WiFi connections"
	sudo rm /etc/NetworkManager/system-connections/*
	echo "....................................................."
	echo "Adding wifi configuration ($ssid)...."
	echo "....................................................."
	count=0
	while true
	do
		read -p "        Ensure you have setup the '$ssid' on Nexus 5X with password '$ssidPassword' Press Enter Key  to continue" ch

		count=$((count+1))
		sudo nmcli d wifi connect $ssid password $ssidPassword
		if [ $? -eq 0 ] ; then
			echo -e "WIFI SSID Configuration succeeded"
			break
		fi
		#Error message
		echo -e "Your WIFI SSID '$ssid' on Nexus 5X is not up or Password '$ssidPassword' is wrong."

		if [ $count -gt 3 ]; then 
			echo -e "Disable / Enable wifi on NVIDIA Shield TV, Check Tethering & portable hotspot in Nexus 5X"
		fi
		read -p "        Please check and press enter to continue..." ans
	done
}

function cron_setup()
{
	cron_file="/home/ubuntu/.nddevice/conf.cron"
	if [ ! -f "$cron_file" ]; then
		touch "$cron_file"
	fi

	echo "*/1 *  * * * export PATH=/usr/local/cuda-7.0/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/home/ubuntu/bin ; export LD_LIBRARY_PATH=/usr/local/cuda-7.0/lib ; export ND_DEVICE_REL_PATH=/home/ubuntu/.nddevice ; export ND_CONFIG_PATH=\$ND_DEVICE_REL_PATH/latest/nd_config.ini ; export ND_INPUT_PATH=/home/iriscli/ND_INPUT ; export ND_OUTPUT_PATH=/home/iriscli/ND_OUTPUT ; /home/ubuntu/bin/wrapper_scheduler" > $cron_file
	echo "@reboot export PATH=/usr/local/cuda-7.0/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/home/ubuntu/bin ; export LD_LIBRARY_PATH=/usr/local/cuda-7.0/lib ; export ND_DEVICE_REL_PATH=/home/ubuntu/.nddevice ; export ND_CONFIG_PATH=\$ND_DEVICE_REL_PATH/latest/nd_config.ini ; export ND_INPUT_PATH=/home/iriscli/ND_INPUT ; export ND_OUTPUT_PATH=/home/iriscli/ND_OUTPUT ; /home/ubuntu/bin/wrapper_cleanupstate" >> $cron_file
	echo "*/10 *  * * * export PATH=/usr/local/cuda-7.0/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/home/ubuntu/bin ; export LD_LIBRARY_PATH=/usr/local/cuda-7.0/lib ; export ND_DEVICE_REL_PATH=/home/ubuntu/.nddevice ; export ND_CONFIG_PATH=\$ND_DEVICE_REL_PATH/latest/nd_config.ini ; export ND_INPUT_PATH=/home/iriscli/ND_INPUT ; export ND_OUTPUT_PATH=/home/iriscli/ND_OUTPUT ; /home/ubuntu/bin/wrapper_otacheck" >> $cron_file
	echo "@reboot touch /home/ubuntu/.nddevice/boot_status && echo 0 > /home/ubuntu/.nddevice/boot_status" >> $cron_file
	#LTE default
        touch /home/ubuntu/.nddevice/session_lte
	echo "@reboot [ -f "/home/ubuntu/.nddevice/session_lte" ] && sudo /home/ubuntu/bin/disable_wifi_turn_on_lte.sh" >> $cron_file
	echo "@reboot [ ! -f "/home/ubuntu/.nddevice/session_lte" ] && sudo /home/ubuntu/bin/disable_lte_turn_wifi_on.sh" >> $cron_file
	
	
	crontab $cron_file
	#GPU frequency

	root_cron_file="/home/ubuntu/.nddevice/root_conf.cron"
	if [ ! -f "$root_cron_file" ]; then
		touch "$root_cron_file"
	fi

	echo "@reboot [ -f "/home/ubuntu/.nddevice/gbusoverride" ] && sudo echo 537600000 >  /sys/kernel/debug/clock/gbus/max" >> $root_cron_file
	echo "@reboot rm -rf /home/iriscli/ND_INPUT/*" >> $root_cron_file
	echo "@reboot rm -rf /home/iriscli/ND_OUTPUT/*" >> $root_cron_file
	echo "@reboot [ -f /home/ubuntu/.nddevice/com_backup ] && [ -d /home/ubuntu/.nddevice/backup/ ] && rm -rf /home/ubuntu/.nddevice/backup/*" >> $root_cron_file
	echo "@reboot [ -s "/home/ubuntu/.nddevice/com_reboot" ] && /home/ubuntu/.nddevice/reboot.sh" >> $root_cron_file
	echo "@reboot [ -f "/home/ubuntu/.nddevice/com_root" ] && sudo /home/ubuntu/.nddevice/command.sh" >> $root_cron_file
	sudo crontab $root_cron_file
        #TODO clean it
	#commented as gbus not required
	#touch /home/ubuntu/.nddevice/gbusoverride
	#backup delete
	touch /home/ubuntu/.nddevice/com_backup
	#reboot command 
	touch /home/ubuntu/.nddevice/com_reboot 
	#default value 
	echo "60" >/home/ubuntu/.nddevice/com_reboot
}

#to make the sdmount point as readonly
function sdcard_mount_readonly()
{
	sudo umount /dev/mmcblk1p1
	mount_status=$?

	if [[ "$mount_status" == "0" ]];then
    		sudo rm -rf /media/SdCard/*
    		cleanup_status=$?

    		if [[ "$cleanup_status" == "0" ]];then
       			sudo chattr +i /media/SdCard
    		fi
	else

		folder_mount="/media/SdCard/"
		#create folder /media/sdcard/
		if [ ! -d "$folder_mount" ]; then
			sudo mkdir -p "$folder_mount"
    			mkdir_status=$?

    			if [[ "$mkdir_status" == "0" ]];then
       				sudo chattr +i $folder_mount
    			fi
			
			echo -e "\t$folder_mount is created with chattr"
		fi 
		

	fi
}
#default value
deviceId="none"
sessionId="none"
ssid="none"
ssidPassword="none"
lanecal="none"
saveMP4="none"
deviceType="none"
deviceSubType="none"
vehClass="none"
profileName="none"
apnName="none"

#Read deviceID and devicetype, subtype
deviceId="$(sudo sys_tx1read | sed -n 's/^Product serial_num:[[:space:]]*//p')"
if [ "$deviceId" == "" ]; then
	deviceId="none"
fi

sudo /bin/revision_icdc
deviceSubType_t="$(echo $?)"

if [ "$deviceSubType_t" == "0" ]; then
	deviceSubType="dvt1"
fi

if [ "$deviceSubType_t" == "1" ]; then
	deviceSubType="dvt2"
fi

if [ "$deviceSubType_t" == "2" ]; then
	deviceSubType="dvt3"
fi

if ! [ -e /bin/revision_icdc ]; then
	deviceSubType="none"
fi

if [ "$deviceId" != "none" ] && [ "$deviceSubType" != "none" ]
then
	deviceType="bagheera"
fi

echo "AUTO Device Id  = $deviceId"
echo "AUTO deviceType  = $deviceType"
echo "AUTO deviceSubType  = $deviceSubType"


#scan the arguments
while true
do
    case "$1" in
    -h | --help)
	Print_Help
	exit 0
	;;
     -deviceId | --deviceId )
        deviceId="$2"
	shift 2
	;;
     -sessionId | --sessionId )
	sessionId="$2"
	shift 2
	;;
     -ssid | --ssid )
	ssid="$2"
	shift 2
	;;

     -ssidPassword | --ssidPassword)
	ssidPassword="$2"
	shift 2
	;; 

     -lanecal | --lanecal)
	lanecal="$2"
	shift 2
	;; 

     -saveMP4 | --saveMP4)
	saveMP4="$2"
	shift 2
	;; 

     -vehClass | --vehClass)
        vehClass="$2"
        shift 2
        ;;

     -device | --deviceType)
        deviceType="$2"
        shift 2
        ;;

     -deviceSub | --deviceSubType)
        deviceSubType="$2"
        shift 2
        ;;


     -profileName | --profileName)
        profileName="$2"
        shift 2
        ;;

     -apnName | --apnName)
        apnName="$2"
        shift 2
        ;;


     *)
	break;;
	
   esac
done

#check if no deviceId then flag the error and error out
if [ "$deviceId" == "none" ]; then
	echo "No Device Id provide exiting ...."
	echo "/bin/sys_tx1read couldnt find Product serial_num"
	Print_Help
	exit;
fi 
echo "Device Id  = $deviceId"

#check if no sessionId then just use the same sessionId as deviceId
if [ "$sessionId" == "none" ]; then
	echo -e "No sessionId is provided \nMaking sessionId same as Device Id = $deviceId"
	sessionId="$deviceId"
fi 
echo "Session Id = $sessionId"

#check if ssid is provided
if [ "$ssid" == "none" ]; then
	echo -e "No wifi ssid is provided \nMaking wifi ssid as = $deviceId"
	ssid="$deviceId"
fi 
echo "ssid = $ssid"

#check if ssid is provided
if [ "$ssidPassword" == "none" ]; then
	echo -e "No wifi password is provided Making wifi ssidPassword as default i.e., 'in37\$12@PA'"
	ssidPassword="in37\$12@PA"
fi 
echo "ssidPassword = $ssidPassword"


#check if lanecal is provided
if [ "$lanecal" == "none" ]; then
	echo -e "No option for lancal is provided making it as none"
	lanecal="none"
fi 
echo "laneCal = $lanecal"

#check if saveMP4 is provided
if [ "$saveMP4" == "none" ]; then
	echo -e "No option for saveMP4 is provided making it as delete"
	saveMP4="delete"
fi 
echo "saveMP4 = $saveMP4"

#check if vehClass is provided 
if [ "$vehClass" == "none" ]; then
	echo -e "No vehClass is provided \nMaking vehClass as default = Class1"
	vehClass="Class1"
fi
echo "vehClass = $vehClass"

#check if deviceType is provided 
if [ "$deviceType" == "none" ]; then
	echo -e "No deviceType is provided \nMaking deviceType as default = bagheera"
	deviceType="bagheera"
fi
echo "deviceType = $deviceType"

#check if deviceSubType is provided 
if [ "$deviceSubType" == "none" ]; then
	echo -e "No deviceSubType is provided \nMaking deviceSubType as default = dvt2"
	deviceSubType="dvt2"
fi
echo "deviceSubType = $deviceSubType"


#check if no profileName then flag the error and error out
if [ "$profileName" == "none" ]; then
        echo "No profileName provided setting default as JIO ...."
        profileName="JIO"
fi
echo "profileName = $profileName"

#check if no apnName then flag the error and error out
if [ "$apnName" == "none" ]; then
        echo "No apnName provided setting default as jionet ...."
        apnName="jionet"
fi

read -p "Press Y|y to contiue ::" ans
if [[ "$ans" == "Y"  ||  "$ans" == "y" ]]; then

	echo "**************STARTING FIRST-TIME CONFIGURATION*********************"		
	delete_default_setup
	#add_user Added as part of image creation 
	add_new_files_conf
	untar_payload
	#install_new_packages #Added for psutils
	cron_setup
	##configure_wifi_ssid
	#add_service #Commented based on the issue BHAGEERA-217  
	sdcard_mount_readonly
	echo "**************FIRST-TIME CONFIGURATION COMPLETED*********************"		
fi

exit 0
